ALTER TABLE "offices" ADD CONSTRAINT "offices_published_fields_check" CHECK ("offices"."status" <> 'published' OR ("offices"."phone_normalized" IS NOT NULL AND length(trim("offices"."phone_normalized")) > 0 AND "offices"."phone_display" IS NOT NULL AND length(trim("offices"."phone_display")) > 0 AND "offices"."address_text" IS NOT NULL AND length(trim("offices"."address_text")) > 0 AND "offices"."published_at" IS NOT NULL AND "offices"."last_verified_at" IS NOT NULL));